// Mesma lista/ids do array OBRAS em prototipo/index.html -- essa API
// exige `obra_id` por chamada (sem endpoint "lista todas as obras"),
// então a lista fixa é inevitável. CNPEM - Auditório (id 103) fica DE
// FORA de propósito, mesma decisão já tomada nos outros fluxos de
// ingestão. Se uma obra nova entrar no painel, adicionar aqui também.
const OBRAS = [
  { id: 106, nome: 'CNPEM - Faseado' },
  { id: 110, nome: 'Hitachi' },
  { id: 94,  nome: 'Porto Itapoá' },
  { id: 107, nome: 'Novo Nordisk - AP' },
  { id: 108, nome: 'Novo Nordisk - AP - Reforço' },
  { id: 91,  nome: 'Novo Nordisk - UB/SP' },
  { id: 114, nome: 'IPEN' },
];

return OBRAS.map(o => ({ json: { id_obra: o.id, nome_obra: o.nome } }));

// Loop processa 1 obra por vez (Split In Batches, batchSize=1) -- ver
// nota no node "Loop obras (1 por vez)". `$('Loop obras (1 por vez)').item.json`
// pega o item ORIGINAL desta volta do loop (id_obra/nome_obra) -- `$json`
// aqui já é a resposta HTTP (o node HTTP substitui o item pelo corpo da
// resposta). Sem loop, isto casava por POSIÇÃO com "Lista de obras";
// com loop, cada execução já é 1 obra só, não precisa mais desse guard.
const idObra = $('Loop obras (1 por vez)').item.json.id_obra;
const nomeObra = $('Loop obras (1 por vez)').item.json.nome_obra;
const corpo = $json;

// Conversão numérica defensiva -- a API irmã (pedidos_usuarios_api) já
// devolveu valor monetário como STRING apesar da doc dizer "número".
const num = (v) => (v === null || v === undefined || v === '') ? null : Number(v);

// FORMATO DO ENVELOPE ainda não 100% confirmado com dado real pra /v1/itens
// -- tenta {data:[...]} (mesmo formato da API irmã), cai pra array direto.
const itens = Array.isArray(corpo?.data) ? corpo.data
  : Array.isArray(corpo) ? corpo
  : (() => { throw new Error(`Formato de resposta inesperado pra obra ${idObra} (nem {data:[...]} nem array direto) -- confira a resposta real e ajuste este node antes de reexecutar.`); })();

const linhas = itens.map(it => ({
  id_obra: idObra,
  obra_nome: nomeObra,
  id_mapa_compras: num(it.id_mapa_compras),
  requisicao: it.requisicao != null ? String(it.requisicao) : null,
  codigo_seq: it.codigo_seq != null ? String(it.codigo_seq) : null,
  descricao: it.descricao || null,
  unidade: it.unidade || null,
  quantidade: num(it.quantidade),
  preco_referencia_bd_s1: num(it.preco_referencia_bd_s1),
  subtotal_referencia_bd_s1: num(it.subtotal_referencia_bd_s1),
  custo_meta_orcamento: num(it.custo_meta_orcamento),
  subtotal_custo_meta_orcamento: num(it.subtotal_custo_meta_orcamento),
  saldo_orcamentario: num(it.saldo_orcamentario),
  saldo_quantidade: num(it.saldo_quantidade),
  quantidade_pedida: num(it.quantidade_pedida),
  total_consumido: num(it.total_consumido),
  tem_pedido: it.tem_pedido === true || it.tem_pedido === 'true' || it.tem_pedido === 1,
  fornecedor_ref: it.fornecedor_ref || null,
  projeto_ref: it.projeto_ref || null,
  // Nomes exatos de melhor_oferta_* não confirmados pela doc -- `raw`
  // guarda o item inteiro, nada se perde mesmo se vierem null.
  melhor_oferta_unitario: num(it.melhor_oferta_unitario),
  melhor_oferta_subtotal: num(it.melhor_oferta_subtotal),
  melhor_oferta_fornecedor: it.melhor_oferta_fornecedor || null,
  raw: it,
  atualizado_em: new Date().toISOString(),
}));

return [{ json: { id_obra: idObra, linhas } }];

// Mesmo padrão de "Montar linhas por obra" -- 1 obra por vez (loop),
// sem precisar casar por posição. Campos confirmados com dado REAL de
// /v1/requisicoes?obra_id=110&per_page=20 (2026-08-31, testado no
// Postman) -- ver tabela requisicoes_mapa_compras (SQL na pasta n8n/).
const idObra = $('Loop obras (1 por vez)').item.json.id_obra;
const nomeObraFallback = $('Loop obras (1 por vez)').item.json.nome_obra;
const corpo = $json;

const num = (v) => (v === null || v === undefined || v === '') ? null : Number(v);
const bool = (v) => v === true || v === 'true' || v === 1;

// FORMATO DO ENVELOPE ainda não 100% confirmado -- tenta {data:[...]},
// cai pra array direto, mesmo padrão do node de itens.
const reqs = Array.isArray(corpo?.data) ? corpo.data
  : Array.isArray(corpo) ? corpo
  : (() => { throw new Error(`Formato de resposta inesperado pra obra ${idObra} (/v1/requisicoes) -- confira a resposta real e ajuste este node antes de reexecutar.`); })();

const linhas = reqs.map(r => ({
  id: num(r.id),
  id_obra: num(r.id_obra) ?? idObra,
  obra: r.obra || nomeObraFallback || null,
  id_rmi: num(r.id_rmi),
  nome_rmi: r.nome_rmi || null,
  requisicao: r.requisicao != null ? String(r.requisicao) : null,
  requisicao_tipo: r.requisicao_tipo || null,
  tipo: r.tipo || null,
  grupo: r.grupo || null,
  categoria: r.categoria || null,
  descricao: r.descricao || null,
  status_requisicao: r.status_requisicao || null,
  status_requisicao_gravado: r.status_requisicao_gravado || null,
  data_cadastro: r.data_cadastro || null,
  data_necessidade: r.data_necessidade || null,
  requisitante: r.requisitante || null,
  cronograma: num(r.cronograma),
  data_cronograma_fechado: r.data_cronograma_fechado || null,
  id_req_original: num(r.id_req_original),
  solicitacao_enviada: bool(r.solicitacao_enviada),
  necessario_contrato: bool(r.necessario_contrato),
  necessario_art: bool(r.necessario_art),
  total_itens: num(r.total_itens),
  // `prazo_execucao` ficou de fora das colunas (só null nas amostras
  // reais, tipo não confirmado) -- continua acessível em `raw`.
  raw: r,
  atualizado_em: new Date().toISOString(),
}));

return [{ json: { id_obra: idObra, linhas } }];
